// פגישה עם תאריך קבוע (מהקליטה או ידני) שעברה: הופכת ל"פגישה אחרונה" והנוסחה החודשית חוזרת — אחרת לא היו עוד פגישות ותזכורות (27.10.26)
function meetRoll_() { const sh = SpreadsheetApp.getActive().getSheetByName(SHEET), today = startOfDay(new Date());
  const rng = sh.getRange(FIRST, C['פגישה הבאה'], ROWS, 1), fx = rng.getFormulas(), vals = rng.getValues(), stv = sh.getRange(FIRST, C['סטטוס'], ROWS, 1).getValues(), lastv = sh.getRange(FIRST, C['פגישה אחרונה'], ROWS, 1).getValues(); let n = 0;
  for (let i = 0; i < ROWS; i++) { const v = vals[i][0]; if (stv[i][0] !== 'פעיל' || fx[i][0] || !(v instanceof Date) || startOfDay(v) >= today) continue; const r = FIRST + i, lv = lastv[i][0];
    if (!(lv instanceof Date) || lv < v) sh.getRange(r, C['פגישה אחרונה']).setValue(Utilities.formatDate(v, 'Asia/Jerusalem', 'dd/MM/yyyy'));
    sh.getRange(r, C['פגישה הבאה']).setFormula(rowFormula('פגישה הבאה', r)); n++; }
  return n; }
